def get_saved_pin():
    try:
        if os.path.exists(PIN_FILE):
            with open(PIN_FILE, "r", encoding="utf-8") as f:
                data = json.load(f)
                return data.get("pin", "1234")
    except Exception:
        pass
    return "1234"

def save_teacher_pin(new_pin):
    try:
        with open(PIN_FILE, "w", encoding="utf-8") as f:
            json.dump({"pin": new_pin}, f, indent=4)
    except Exception:
        pass

