# --- Data Helper Functions ---
def load_json_file(filename, default_val):
    if os.path.exists(filename):
        try:
            with open(filename, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return default_val
    return default_val

def save_json_file(filename, data):
    with open(filename, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=4, ensure_ascii=False)

# --- PDF Scorecard Generator ---
def generate_pdf_report(student_name, phone_no, test_title, score, max_marks, pct, time_spent, strong_topics, weak_topics):
    buffer = BytesIO()
    if HAS_REPORTLAB:
        doc = SimpleDocTemplate(buffer, pagesize=letter, rightMargin=30, leftMargin=30, topMargin=30, bottomMargin=30)
        styles = getSampleStyleSheet()
        
        title_style = ParagraphStyle('TitleStyle', parent=styles['Heading1'], fontSize=18, textColor=colors.HexColor('#1e3c72'), alignment=1, spaceAfter=15)
        subtitle_style = ParagraphStyle('SubStyle', parent=styles['Normal'], fontSize=11, alignment=1, spaceAfter=20)
        section_style = ParagraphStyle('SecStyle', parent=styles['Heading2'], fontSize=13, textColor=colors.HexColor('#2a5298'), spaceBefore=10, spaceAfter=10)
        body_style = ParagraphStyle('BodyStyle', parent=styles['Normal'], fontSize=10, spaceAfter=6)

        elements = []
        elements.append(Paragraph("<b>SENTINELYOGI MOCK TEST PORTAL</b>", title_style))
        elements.append(Paragraph(f"<b>Official Performance & Diagnostic Scorecard</b><br/>Exam: {test_title}", subtitle_style))
        
        summary_data = [
            [Paragraph("<b>Student Name:</b>", body_style), Paragraph(student_name, body_style), Paragraph("<b>Phone Number:</b>", body_style), Paragraph(phone_no, body_style)],
            [Paragraph("<b>Score Obtained:</b>", body_style), Paragraph(f"{score:.2f} / {max_marks:.2f}", body_style), Paragraph("<b>Percentage:</b>", body_style), Paragraph(f"{pct:.1f}%", body_style)],
            [Paragraph("<b>Time Spent:</b>", body_style), Paragraph(time_spent, body_style), Paragraph("<b>Result Status:</b>", body_style), Paragraph("PASSED" if pct >= 40 else "NEEDS IMPROVEMENT", body_style)]
        ]
        
        t = Table(summary_data, colWidths=[110, 150, 110, 150])
        t.setStyle(TableStyle([
            ('BACKGROUND', (0,0), (-1,-1), colors.HexColor('#f8f9fa')),
            ('GRID', (0,0), (-1,-1), 0.5, colors.HexColor('#dee2e6')),
            ('PADDING', (0,0), (-1,-1), 6),
        ]))
        elements.append(t)
        elements.append(Spacer(1, 15))
        
        elements.append(Paragraph("<b>Diagnostic Subject & Topic Analysis</b>", section_style))
        
        strong_str = ", ".join(strong_topics) if strong_topics else "None"
        weak_str = ", ".join(weak_topics) if weak_topics else "None"
        
        diag_data = [
            [Paragraph("<b>🟢 Strong Topics (≥75% Accuracy):</b>", body_style), Paragraph(strong_str, body_style)],
            [Paragraph("<b>🔴 Areas Needing Focus (<50% Accuracy):</b>", body_style), Paragraph(weak_str, body_style)]
        ]
        
        t_diag = Table(diag_data, colWidths=[200, 320])
        t_diag.setStyle(TableStyle([
            ('BACKGROUND', (0,0), (-1,-1), colors.HexColor('#ffffff')),
            ('GRID', (0,0), (-1,-1), 0.5, colors.HexColor('#ced4da')),
            ('PADDING', (0,0), (-1,-1), 6),
        ]))
        elements.append(t_diag)
        
        elements.append(Spacer(1, 20))
        elements.append(Paragraph("<i>This scorecard is system generated by SentinelYogi Practice & Exam Engine.</i>", ParagraphStyle('Foot', parent=styles['Italic'], fontSize=9, alignment=1)))
        
        doc.build(elements)
    else:
        # Fallback text scorecard when reportlab is not installed
        report_txt = f"""====================================================
SENTINELYOGI MOCK TEST PORTAL
Official Candidate Scorecard
====================================================
Student Name : {student_name}
Phone Number : {phone_no}
Exam Paper   : {test_title}
Score        : {score:.2f} / {max_marks:.2f}
Percentage   : {pct:.1f}%
Time Spent   : {time_spent}
Result Status: {"PASSED" if pct >= 40 else "NEEDS IMPROVEMENT"}

----------------------------------------------------
DIAGNOSTIC TOPIC ANALYSIS
----------------------------------------------------
Strong Topics (>=75% Accuracy):
{", ".join(strong_topics) if strong_topics else "None"}

Areas Needing Focus (<50% Accuracy):
{", ".join(weak_topics) if weak_topics else "None"}

====================================================
Generated by SentinelYogi Exam Engine
===================================================="""
        buffer.write(report_txt.encode('utf-8'))
    
    buffer.seek(0)
    return buffer


# --- Admin Security Helper ---
def check_admin_password():
    if st.session_state.get("admin_authenticated", False):
        return True
    
    st.title("🔒 Teacher & Admin Security Verification")
    st.info("⚠️ This area contains sensitive student results, rankings, and test management controls. Please enter your Teacher Security PIN to proceed.")
    
    pin_input = st.text_input("Enter Teacher Security PIN / Password:", type="password", key="admin_pin_input")
    
    col_p1, col_p2 = st.columns([1, 2])
    if col_p1.button("🔓 Unlock Admin Access", type="primary"):
        if pin_input == st.session_state.get("teacher_pin", "1234"):
            st.session_state.admin_authenticated = True
            st.success("✅ Access Granted!")
            st.rerun()
        else:
            st.error("❌ Incorrect Password! Default PIN is '1234' unless changed.")
            
    st.caption("💡 Default Teacher PIN is **1234**. You can change it once unlocked.")
    return False

