st.session_state.lang = st.sidebar.radio("Select Language / भाषा चुनें:", ["English", "Hindi / हिंदी"], index=0 if st.session_state.lang == "English" else 1)

# =========================================================
# MODE 1: REAL EXAM TEST INTERFACE (TCS iON STYLE)
# =========================================================
if app_mode == "📝 Real Exam Test Interface":
    st.title("📝 Online Examination Center")
    
    test_names = list(st.session_state.tests.keys())
    
    if not test_names:
        st.warning("No tests available in the portal. Go to '➕ Teacher Test Series Creator' to add a test paper!")
    else:
        selected_test = st.selectbox("Select Target Examination Paper:", test_names)
        t_data = st.session_state.tests[selected_test]
        
        pos_m = t_data.get("positive_marks", 2.0)
        neg_m = t_data.get("negative_marks", 0.25)
        duration = t_data.get("duration_minutes", 15)
        questions = t_data["questions"]
        max_m = len(questions) * pos_m

        # Top Information Banner
        st.info(f"📋 **Paper:** {t_data.get('title', selected_test)} | ⏱️ **Time Limit:** {duration} Mins | ➕ **Correct:** +{pos_m} | ➖ **Penalty:** -{neg_m}")

        # Reset session state if switching active test
        if "active_test_key" not in st.session_state or st.session_state.active_test_key != selected_test:
            st.session_state.active_test_key = selected_test
            st.session_state.user_answers = {}
            st.session_state.review_states = {}
            st.session_state.test_submitted = False
            st.session_state.start_time = None
            st.session_state.current_q_idx = 0

        if not st.session_state.test_submitted:
            st.markdown("---")
            st.subheader("👤 Student Registration & Verification")
            c_s1, c_s2 = st.columns(2)
            s_name = c_s1.text_input("Full Candidate Name*", value=st.session_state.student_info.get("name", ""))
            s_phone = c_s2.text_input("Phone Number*", value=st.session_state.student_info.get("phone_no", ""))
            
            st.session_state.student_info["name"] = s_name
            st.session_state.student_info["phone_no"] = s_phone

            if not s_name.strip() or not s_phone.strip():
                st.warning("⚠️ Please fill in your Candidate Name and Phone Number above to unlock the exam paper.")
            else:
                if st.session_state.start_time is None:
                    if st.button("🚀 Start Examination Now", type="primary", use_container_width=True):
                        st.session_state.start_time = time.time()
                        st.rerun()
                else:
                    # Timer Calculation
                    elapsed = time.time() - st.session_state.start_time
                    rem_seconds = max(0, int((duration * 60) - elapsed))
                    rem_m, rem_s = divmod(rem_seconds, 60)

                    col_timer, col_pal_legend = st.columns([1, 2])
                    with col_timer:
                        st.markdown(f"### ⏱️ Time Left: `{rem_m:02d}:{rem_s:02d}`")
                        if rem_seconds <= 0:
                            st.error("⏰ Time Expired! Auto-submitting your test paper...")
                            st.session_state.test_submitted = True
                            st.rerun()

                    with col_pal_legend:
                        st.markdown("""
                        **Question Palette Status:**
                        ⚪ Not Visited | 🔴 Not Answered | 🟢 Answered | 🟣 Marked for Review
                        """)

                    st.markdown("---")
                    
                    # Main Exam Split View (Left: Question | Right: TCS iON Palette)
                    col_q_area, col_palette = st.columns([3, 1])

                    q_idx = st.session_state.current_q_idx
                    curr_q = questions[q_idx]

                    with col_q_area:
                        st.subheader(f"Question No. {q_idx + 1} of {len(questions)}")
                        st.caption(f"Topic: `{curr_q.get('topic', 'General')}`")
                        
                        st.markdown(f"#### {curr_q['question']}")

                        # Get Options
                        opts = curr_q["options"]
                        if isinstance(opts, dict):
                            opt_list = [f"{k}) {v}" for k, v in opts.items()]
                        else:
                            opt_list = opts

                        saved_ans = st.session_state.user_answers.get(q_idx, None)
                        
                        selected = st.radio(
                            "Choose your answer:",
                            options=opt_list,
                            index=opt_list.index(saved_ans) if saved_ans in opt_list else None,
                            key=f"radio_q_{q_idx}"
                        )

                        # Navigation Action Buttons
                        c_act1, c_act2, c_act3, c_act4 = st.columns(4)
                        
                        if c_act1.button("💾 Save & Next", type="primary"):
                            if selected:
                                st.session_state.user_answers[q_idx] = selected
                            if q_idx < len(questions) - 1:
                                st.session_state.current_q_idx += 1
                            st.rerun()

                        if c_act2.button("🟣 Mark for Review"):
                            st.session_state.review_states[q_idx] = True
                            if selected:
                                st.session_state.user_answers[q_idx] = selected
                            if q_idx < len(questions) - 1:
                                st.session_state.current_q_idx += 1
                            st.rerun()

                        if c_act3.button("🧹 Clear Response"):
                            if q_idx in st.session_state.user_answers:
                                del st.session_state.user_answers[q_idx]
                            if q_idx in st.session_state.review_states:
                                del st.session_state.review_states[q_idx]
                            st.rerun()

                        if c_act4.button("🚀 Final Submit Exam"):
                            st.session_state.test_submitted = True
                            st.rerun()

                    # Question Palette
                    with col_palette:
                        st.markdown("### Question Palette")
                        pal_cols = st.columns(4)
                        for idx in range(len(questions)):
                            col_i = pal_cols[idx % 4]
                            
                            ans = st.session_state.user_answers.get(idx)
                            is_rev = st.session_state.review_states.get(idx, False)

                            if is_rev:
                                btn_label = f"🟣 {idx+1}"
                            elif ans is not None:
                                btn_label = f"🟢 {idx+1}"
                            elif idx == q_idx:
                                btn_label = f"🔴 {idx+1}"
                            else:
                                btn_label = f"⚪ {idx+1}"

                            if col_i.button(btn_label, key=f"pal_btn_{idx}"):
                                st.session_state.current_q_idx = idx
                                st.rerun()

        # =========================================================
        # SUBMITTED STATE / DETAILED RESULTS & DIAGNOSTICS
        # =========================================================
        else:
            st.balloons()
            st.success("🎉 Examination Submitted Successfully!")

            correct_count = 0
            wrong_count = 0
            unattempted_count = 0
            
            topic_stats = {}

            for idx, q in enumerate(questions):
                top = q.get("topic", "General")
                if top not in topic_stats:
                    topic_stats[top] = {"total": 0, "correct": 0, "wrong": 0, "unattempted": 0}
                
                topic_stats[top]["total"] += 1
                
                user_ans = st.session_state.user_answers.get(idx)
                
                # Normalize Correct Answer
                opts = q["options"]
                if isinstance(opts, dict):
                    correct_idx = q.get("answer_idx", 0)
                    correct_key = list(opts.keys())[correct_idx] if isinstance(correct_idx, int) else q.get("correct_answer", "A")
                    correct_val = f"{correct_key}) {opts[correct_key]}"
                else:
                    c_idx = q.get("answer_idx", 0)
                    correct_val = opts[c_idx] if isinstance(c_idx, int) and c_idx < len(opts) else opts[0]

                if user_ans is None:
                    unattempted_count += 1
                    topic_stats[top]["unattempted"] += 1
                elif user_ans == correct_val:
                    correct_count += 1
                    topic_stats[top]["correct"] += 1
                else:
                    wrong_count += 1
                    topic_stats[top]["wrong"] += 1

            raw_score = (correct_count * pos_m) - (wrong_count * neg_m)
            pct = round((raw_score / max_m) * 100, 1) if max_m > 0 else 0
            time_spent_sec = int(time.time() - st.session_state.start_time) if st.session_state.start_time else 0
            time_spent_str = f"{time_spent_sec // 60}m {time_spent_sec % 60}s"

            # Determine Topic Diagnostics
            strong_topics = []
            weak_topics = []
            for top, stats in topic_stats.items():
                acc = (stats["correct"] / stats["total"]) * 100 if stats["total"] > 0 else 0
                if acc >= 75:
                    strong_topics.append(top)
                elif acc < 50:
                    weak_topics.append(top)

            # Score Summary Cards
            st.markdown("### 📊 Official Candidate Scorecard")
            sc1, sc2, sc3, sc4, sc5 = st.columns(5)
            sc1.metric("Candidate Name", st.session_state.student_info["name"])
            sc2.metric("Raw Score", f"{raw_score:.2f} / {max_m:.2f}")
            sc3.metric("Percentage", f"{pct}%")
            sc4.metric("Accuracy", f"{round((correct_count / (correct_count + wrong_count)) * 100, 1) if (correct_count + wrong_count) > 0 else 0}%")
            sc5.metric("Time Taken", time_spent_str)

            # PDF Download Button
            pdf_buf = generate_pdf_report(
                st.session_state.student_info["name"],
                st.session_state.student_info.get("phone_no", st.session_state.student_info.get("roll_no", "")),
                selected_test,
                raw_score,
                max_m,
                pct,
                time_spent_str,
                strong_topics,
                weak_topics
            )
            
            if HAS_REPORTLAB:
                st.download_button(
                    label="📄 Download Official PDF Scorecard Report",
                    data=pdf_buf,
                    file_name=f"Scorecard_{st.session_state.student_info.get('phone_no', 'result')}.pdf",
                    mime="application/pdf",
                    type="primary"
                )
            else:
                st.download_button(
                    label="📄 Download Official Scorecard (Text Summary)",
                    data=pdf_buf,
                    file_name=f"Scorecard_{st.session_state.student_info.get('phone_no', 'result')}.txt",
                    mime="text/plain",
                    type="primary"
                )
                st.caption("💡 *To enable PDF download formatting, run `py -m pip install reportlab` in your Command Prompt.*")

            # Diagnostic Analysis
            st.markdown("---")
            st.subheader("🎯 Subject & Topic Mastery Diagnostics")
            col_st, col_wt = st.columns(2)
            with col_st:
                st.markdown("#### 🟢 Strong Topics (≥75% Accuracy)")
                for t in strong_topics:
                    st.success(f"• {t}")
                if not strong_topics:
                    st.write("None identified in this attempt.")

            with col_wt:
                st.markdown("#### 🔴 Areas Needing Improvement (<50% Accuracy)")
                for t in weak_topics:
                    st.error(f"• {t}")
                if not weak_topics:
                    st.write("Excellent! No weak topics detected.")

            # Save Results
            rec = {
                "name": st.session_state.student_info["name"],
                "roll_no": st.session_state.student_info.get("phone_no", st.session_state.student_info.get("roll_no", "")),
                "test_title": selected_test,
                "score": raw_score,
                "max_marks": max_m,
                "percentage": pct,
                "time_spent": time_spent_str,
                "date": time.strftime("%Y-%m-%d %H:%M")
            }
            st.session_state.results.append(rec)
            save_json_file(RESULTS_FILE, st.session_state.results)

            if st.button("🔄 Attempt Another Test"):
                st.session_state.test_submitted = False
                st.session_state.user_answers = {}
                st.session_state.start_time = None
                st.rerun()

